options.styles:
.exec-header-card {
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 16px;
  background: linear-gradient(135deg, #0F172A 0%, #1E293B 100%);
  border: 1px solid #334155;
  border-left: 5px solid #EA580C;
  border-radius: 8px;
  padding: 16px 22px;
  box-shadow: 0 4px 20px rgba(0, 0, 0, 0.4);
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  color: #F8FAFC;
}
.exec-header-left {
  display: flex;
  align-items: center;
  gap: 16px;
}
.exec-logo-badge {
  background: #EA580C;
  color: #FFFFFF;
  font-weight: 900;
  font-size: 13px;
  letter-spacing: 0.1em;
  padding: 8px 14px;
  border-radius: 6px;
  box-shadow: 0 2px 8px rgba(234, 88, 12, 0.4);
}
.exec-title-block {
  display: flex;
  flex-direction: column;
  gap: 4px;
}
.exec-title {
  margin: 0;
  font-size: 20px;
  font-weight: 800;
  color: #F8FAFC;
  letter-spacing: -0.01em;
}
.exec-subtitle {
  margin: 0;
  font-size: 12px;
  color: #94A3B8;
}
.exec-header-right {
  display: flex;
  align-items: center;
  gap: 10px;
  flex-wrap: wrap;
}
.exec-stat-chip {
  display: flex;
  flex-direction: column;
  background: rgba(15, 23, 42, 0.7);
  border: 1px solid #334155;
  border-radius: 6px;
  padding: 6px 12px;
  min-width: 95px;
}
.exec-stat-chip.highlight {
  border-color: #22C55E;
  background: rgba(34, 197, 94, 0.12);
}
.chip-label {
  font-size: 9px;
  font-weight: 800;
  color: #94A3B8;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}
.chip-val {
  font-size: 12px;
  font-weight: 800;
  color: #F8FAFC;
  margin-top: 2px;
}
.exec-stat-chip.highlight .chip-val {
  color: #4ADE80;
}

.svc-table-container {
  background: #0B0F19;
  border: 1px solid #1E293B;
  border-radius: 8px;
  padding: 12px 16px;
  overflow-x: auto;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  color: #F8FAFC;
}
.svc-table {
  width: 100%;
  border-collapse: collapse;
}
.svc-table thead th {
  background: #0F172A;
  color: #94A3B8;
  font-size: 10px;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  padding: 10px 12px;
  border-bottom: 2px solid #334155;
  text-align: left;
}
.svc-table tbody tr {
  border-bottom: 1px solid #1E293B;
  transition: background 0.15s ease;
}
.svc-table tbody tr:hover {
  background: rgba(56, 189, 248, 0.05);
}
.svc-table tbody td {
  padding: 10px 12px;
  font-size: 12px;
  vertical-align: middle;
}
.svc-name-group {
  display: flex;
  align-items: center;
  gap: 12px;
}
.svc-icon {
  font-size: 20px;
}
.svc-title {
  font-weight: 700;
  color: #F1F5F9;
  font-size: 13px;
}
.svc-desc {
  font-size: 11px;
  color: #64748B;
  margin-top: 1px;
}
.svc-assets {
  font-size: 11px;
  color: #94A3B8;
  font-family: monospace;
}
.slo-target {
  font-weight: 700;
  color: #CBD5E1;
  font-size: 12px;
}
.sli-val {
  font-weight: 800;
  font-size: 13px;
}
.sli-val.ok {
  color: #4ADE80;
}
.sli-val.warn {
  color: #FBBF24;
}
.sli-val.bad {
  color: #F87171;
}
.budget-badge {
  display: inline-block;
  padding: 3px 8px;
  border-radius: 4px;
  font-size: 11px;
  font-weight: 700;
}
.budget-badge.safe {
  background: rgba(34, 197, 94, 0.15);
  color: #4ADE80;
  border: 1px solid rgba(34, 197, 94, 0.3);
}
.budget-badge.warn {
  background: rgba(239, 68, 68, 0.15);
  color: #F87171;
  border: 1px solid rgba(239, 68, 68, 0.3);
}
.status-pill {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 4px 10px;
  border-radius: 12px;
  font-size: 11px;
  font-weight: 800;
}
.status-pill.success {
  background: rgba(22, 163, 74, 0.2);
  color: #4ADE80;
  border: 1px solid #16A34A;
}
.status-pill.warning {
  background: rgba(245, 158, 11, 0.2);
  color: #FBBF24;
  border: 1px solid #F59E0B;
}

.inc-log-container {
  background: #0B0F19;
  border: 1px solid #1E293B;
  border-radius: 8px;
  padding: 12px 16px;
  overflow-x: auto;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  color: #F8FAFC;
}
.inc-table {
  width: 100%;
  border-collapse: collapse;
}
.inc-table thead th {
  background: #0F172A;
  color: #94A3B8;
  font-size: 10px;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  padding: 10px 12px;
  border-bottom: 2px solid #334155;
  text-align: left;
}
.inc-table tbody tr {
  border-bottom: 1px solid #1E293B;
}
.inc-table tbody td {
  padding: 9px 12px;
  font-size: 11.5px;
  vertical-align: middle;
}
.inc-time {
  color: #94A3B8;
  font-family: monospace;
}
.inc-svc {
  font-weight: 700;
  color: #F1F5F9;
}
.inc-desc {
  color: #CBD5E1;
}
.inc-dur {
  font-weight: 700;
  color: #FB923C;
}
.inc-sev {
  display: inline-block;
  padding: 2px 6px;
  border-radius: 4px;
  font-size: 10px;
  font-weight: 800;
}
.inc-sev.p1 {
  background: rgba(220, 38, 38, 0.2);
  color: #F87171;
  border: 1px solid #DC2626;
}
.inc-sev.p2 {
  background: rgba(234, 88, 12, 0.2);
  color: #FB923C;
  border: 1px solid #EA580C;
}
.inc-sev.p3 {
  background: rgba(59, 130, 246, 0.2);
  color: #60A5FA;
  border: 1px solid #3B82F6;
}
.inc-act {
  color: #94A3B8;
  font-size: 11px;
}
